def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    num_str = str(abs(num))  # ignore the sign
    even_count = 0
    odd_count = 0
    for ch in num_str:
        digit = int(ch)
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def max_aggregate(pairs):
    """
    Return the tuple with the maximum aggregate score.
    """
    best_name, best_score = pairs[0]
    for name, score in pairs[1:]:
        total = score + best_score if name == best_name else score
        if total > best_score:
            best_name, best_score = name, total
    return (best_name, best_score)

assert max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)]) == ('Juan Whelan', 212)

